int failed = 0;
foreach (var test in tests)
{
    var watch = Stopwatch.StartNew();
    try
    {
        int timeoutSeconds = test.Name == Erlang.Tests.HaltSubprocessHostNames.Test
            ? Erlang.Tests.HaltSubprocessHostNames.OuterHostBudgetSeconds
            : 15;
        await test.Body().WaitAsync(TimeSpan.FromSeconds(timeoutSeconds));
        Console.WriteLine("PASS " + test.Name);
        results.Add(new
        {
            test.Name,
            Status = "Passed",
            Milliseconds = watch.ElapsedMilliseconds
        });
    }
    catch (Exception ex)
    {
        failed++;
        Console.WriteLine("FAIL " + test.Name + ": " + ex);
        results.Add(new
        {
            test.Name,
            Status = "Failed",
            Error = ex.ToString(),
            Milliseconds = watch.ElapsedMilliseconds
        });
    }
}
Console.WriteLine($"{tests.Count - failed}/{tests.Count} passed");
string? report = args.FirstOrDefault();
if (report is not null)
{
    Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(report))!);
    await File.WriteAllTextAsync(
        report,
        JsonSerializer.Serialize(new
        {
            Passed = tests.Count - failed,
            Failed = failed,
            Tests = results
        }, new JsonSerializerOptions { WriteIndented = true })
    );
}
if (failed == 0 && args.Length > 1)
    await File.WriteAllTextAsync(
        args[1],
        JsonSerializer.Serialize(
            exportRegistry.Exports.Select(e => new { e.Module, e.Function, e.Arity, Status = "Partially compatible", Evidence = $"mfa/{e.Module}:{e.Function}/{e.Arity}", Limits = "Single direct contract case plus feature regressions; complete error/options and OTP differential verification pending" }),
            new JsonSerializerOptions { WriteIndented = true }
        )
    );
return failed == 0 ? 0 : 1;
